create table public.attendance_qr_sessions (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,classroom_id uuid not null references public.classrooms(id) on delete restrict,token_hash text not null unique,opens_at timestamptz not null,expires_at timestamptz not null,is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),check(expires_at>opens_at));create index attendance_qr_sessions_tenant_idx on public.attendance_qr_sessions(tenant_id,expires_at);alter table public.attendance_qr_sessions enable row level security;revoke all on public.attendance_qr_sessions from anon,authenticated;create policy attendance_qr_select_tenant on public.attendance_qr_sessions for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('attendance_qr.read','Read attendance QR sessions','View QR sessions'),('attendance_qr.create','Create attendance QR sessions','Start QR sessions'),('attendance_qr.update','Update attendance QR sessions','Maintain QR sessions'),('attendance_qr.delete','Delete attendance QR sessions','Delete QR sessions') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'attendance_qr.%' on conflict do nothing;
